xml.Script:
        clYellow  := 'FFFF00';
        clBlue    := '3030FF';
        clGreen   := '00C000';
        clRed1    := 'FF0000';
        clRed2    := 'FF0001';
        clRed3    := 'FF0100';
        clYellow1 := 'FFFF01';
        clBlue1   := '3030FE';
        clGreen1  := '00C001';
        clOrange  := 'FF6A00';

        R := 0.7;
        include 'Figures\Scripts\Icosahedron_Coordinates.inc';

        C0 := R * (1 + sqrt(5)) / 4;
        C1 := R * (3 + 4 * sqrt(2) + sqrt(5)) / 12;
        C2 := R / 2;

        S0 :=  C2 + 2 * C0;
        S1 :=  C0 + 2 * C2;
        S2 :=  C2 - 2 * C0;

        Sc := R / RSin / 5;

        X := 0;
        Y := S1 * Sc;
        Z := S2 * Sc;

        X1 := X;
        X2 := X - C0 - C2;
        Y1 := Y;
        Y2 := Y + C2;
        Z1 := Z - 2 * C0;
        Z2 := Z - C0;

        jumAngle := Arcsin(1/4) + Pi/6;

        D := R * 0.025;
